<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Autonomous Neon Snake</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }
    body {
      background-color: #08080c;
      color: #fff;
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
      overflow: hidden;
    }
    .hud {
      display: flex;
      gap: 32px;
      margin-bottom: 20px;
      font-size: 1.2rem;
      letter-spacing: 2px;
      text-transform: uppercase;
    }
    .hud span {
      color: #00ff88;
      font-weight: bold;
      text-shadow: 0 0 10px rgba(0, 255, 136, 0.5);
    }
    .canvas-container {
      position: relative;
      border: 2px solid #1a1a28;
      border-radius: 8px;
      box-shadow: 0 0 30px rgba(0, 255, 136, 0.1), inset 0 0 20px rgba(0, 0, 0, 0.8);
      background: #0d0d15;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>

  <div class="hud">
    <div>Score: <span id="score">0</span></div>
    <div>Best: <span id="high-score">0</span></div>
  </div>

  <div class="canvas-container">
    <canvas id="gameCanvas" width="400" height="400"></canvas>
  </div>

  <script>
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');
    const scoreEl = document.getElementById('score');
    const highScoreEl = document.getElementById('high-score');

    const GRID_SIZE = 20;
    const TILE_SIZE = canvas.width / GRID_SIZE;
    const SPEED = 70; // milliseconds per step

    let snake = [];
    let food = { x: 0, y: 0 };
    let score = 0;
    let highScore = 0;

    function resetGame() {
      score = 0;
      scoreEl.textContent = score;
      snake = [
        { x: 10, y: 10 },
        { x: 10, y: 11 },
        { x: 10, y: 12 }
      ];
      spawnFood();
    }

    function spawnFood() {
      const emptyCells = [];
      for (let x = 0; x < GRID_SIZE; x++) {
        for (let y = 0; y < GRID_SIZE; y++) {
          if (!snake.some(segment => segment.x === x && segment.y === y)) {
            emptyCells.push({ x, y });
          }
        }
      }
      if (emptyCells.length > 0) {
        food = emptyCells[Math.floor(Math.random() * emptyCells.length)];
      }
    }

    // Breadth-First Search to find the shortest path to food
    function bfs(start, target, obstacleList) {
      const queue = [[start]];
      const visited = new Set();
      visited.add(`${start.x},${start.y}`);

      // Allow head to step onto the tail tip since it vacates next tick
      const obstacles = new Set(
        obstacleList.slice(0, -1).map(p => `${p.x},${p.y}`)
      );

      const dirs = [
        { x: 0, y: -1 }, // Up
        { x: 1, y: 0 },  // Right
        { x: 0, y: 1 },  // Down
        { x: -1, y: 0 }  // Left
      ];

      while (queue.length > 0) {
        const path = queue.shift();
        const cur = path[path.length - 1];

        if (cur.x === target.x && cur.y === target.y) {
          return path.slice(1);
        }

        for (const d of dirs) {
          const nx = cur.x + d.x;
          const ny = cur.y + d.y;
          const key = `${nx},${ny}`;

          if (
            nx >= 0 && nx < GRID_SIZE &&
            ny >= 0 && ny < GRID_SIZE &&
            !obstacles.has(key) &&
            !visited.has(key)
          ) {
            visited.add(key);
            queue.push([...path, { x: nx, y: ny }]);
          }
        }
      }
      return null;
    }

    // Flood fill to determine survivable area if path to food is blocked
    function countFreeSpaces(start, obstacleList) {
      const queue = [start];
      const visited = new Set();
      visited.add(`${start.x},${start.y}`);
      const obstacles = new Set(obstacleList.map(p => `${p.x},${p.y}`));

      const dirs = [{ x: 0, y: -1 }, { x: 1, y: 0 }, { x: 0, y: 1 }, { x: -1, y: 0 }];
      let count = 0;

      while (queue.length > 0) {
        const cur = queue.shift();
        count++;

        for (const d of dirs) {
          const nx = cur.x + d.x;
          const ny = cur.y + d.y;
          const key = `${nx},${ny}`;

          if (
            nx >= 0 && nx < GRID_SIZE &&
            ny >= 0 && ny < GRID_SIZE &&
            !obstacles.has(key) &&
            !visited.has(key)
          ) {
            visited.add(key);
            queue.push({ x: nx, y: ny });
          }
        }
      }
      return count;
    }

    function getNextMove() {
      const head = snake[0];
      const path = bfs(head, food, snake);

      if (path && path.length > 0) {
        return path[0];
      }

      // Fallback: choose the neighboring cell with the most open space
      const dirs = [{ x: 0, y: -1 }, { x: 1, y: 0 }, { x: 0, y: 1 }, { x: -1, y: 0 }];
      let bestMove = null;
      let maxSpace = -1;

      for (const d of dirs) {
        const next = { x: head.x + d.x, y: head.y + d.y };
        const key = `${next.x},${next.y}`;
        const isWall = next.x < 0 || next.x >= GRID_SIZE || next.y < 0 || next.y >= GRID_SIZE;
        const isBody = snake.slice(0, -1).some(seg => seg.x === next.x && seg.y === next.y);

        if (!isWall && !isBody) {
          const space = countFreeSpaces(next, snake);
          if (space > maxSpace) {
            maxSpace = space;
            bestMove = next;
          }
        }
      }
      return bestMove;
    }

    function update() {
      const nextMove = getNextMove();

      if (!nextMove) {
        resetGame();
        return;
      }

      // Check collision with walls or self
      if (
        nextMove.x < 0 || nextMove.x >= GRID_SIZE ||
        nextMove.y < 0 || nextMove.y >= GRID_SIZE ||
        snake.some(segment => segment.x === nextMove.x && segment.y === nextMove.y)
      ) {
        resetGame();
        return;
      }

      snake.unshift(nextMove);

      if (nextMove.x === food.x && nextMove.y === food.y) {
        score++;
        scoreEl.textContent = score;
        if (score > highScore) {
          highScore = score;
          highScoreEl.textContent = highScore;
        }
        spawnFood();
      } else {
        snake.pop();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Subtle background grid
      ctx.strokeStyle = '#12121e';
      ctx.lineWidth = 1;
      for (let i = 0; i <= GRID_SIZE; i++) {
        ctx.beginPath();
        ctx.moveTo(i * TILE_SIZE, 0);
        ctx.lineTo(i * TILE_SIZE, canvas.height);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(0, i * TILE_SIZE);
        ctx.lineTo(canvas.width, i * TILE_SIZE);
        ctx.stroke();
      }

      // Draw Neon Food
      ctx.save();
      ctx.shadowBlur = 15;
      ctx.shadowColor = '#ff0055';
      ctx.fillStyle = '#ff0055';
      ctx.beginPath();
      ctx.arc(
        food.x * TILE_SIZE + TILE_SIZE / 2,
        food.y * TILE_SIZE + TILE_SIZE / 2,
        TILE_SIZE / 2 - 3,
        0,
        Math.PI * 2
      );
      ctx.fill();
      ctx.restore();

      // Draw Neon Snake
      ctx.save();
      ctx.shadowBlur = 12;
      ctx.shadowColor = '#00ff88';

      snake.forEach((segment, index) => {
        // Head is slightly brighter
        ctx.fillStyle = index === 0 ? '#b3ffdb' : '#00ff88';
        const padding = 2;
        ctx.fillRect(
          segment.x * TILE_SIZE + padding,
          segment.y * TILE_SIZE + padding,
          TILE_SIZE - padding * 2,
          TILE_SIZE - padding * 2
        );
      });
      ctx.restore();
    }

    function gameLoop() {
      update();
      draw();
    }

    resetGame();
    setInterval(gameLoop, SPEED);
  </script>
</body>
</html>
```

The game uses Breadth-First Search (BFS) to compute the shortest path from the snake's head to the food on every frame, seamlessly falling back to a flood-fill survival algorithm to maximize open space and avoid self-trapping whenever the path is blocked.
